// BankBazaar HTML Parser
const cheerio = require('cheerio');
const html = $input.first().json.data;
const $ = cheerio.load(html);

const products = [];

// Parse loan products (adjust selectors based on actual HTML)
$('.loan-product-card').each((i, element) => {
  const $el = $(element);

  const product = {
    product_name: $el.find('.product-name').text().trim(),
    lender_name: $el.find('.lender-name').text().trim(),
    interest_rate_min: parseFloat($el.find('.rate-min').text().replace(/[^0-9.]/g, '')),
    interest_rate_max: parseFloat($el.find('.rate-max').text().replace(/[^0-9.]/g, '')),
    loan_amount_min: parseFloat($el.find('.amount-min').text().replace(/[^0-9]/g, '')),
    loan_amount_max: parseFloat($el.find('.amount-max').text().replace(/[^0-9]/g, '')),
    min_monthly_income: parseFloat($el.find('.min-income').text().replace(/[^0-9]/g, '')),
    min_credit_score: parseInt($el.find('.min-credit').text().replace(/[^0-9]/g, '')),
    employment_types: ['Salaried', 'Self-Employed'], // Default
    min_age: 21,
    max_age: 60,
    source_url: 'https://www.bankbazaar.com/personal-loan.html'
  };

  if (product.product_name && product.lender_name) {
    products.push(product);
  }
});

return products.map(product => ({ json: product }));

// PaisaBazaar HTML Parser
const cheerio = require('cheerio');
const html = $input.first().json.data;
const $ = cheerio.load(html);

const products = [];

// Parse loan products (adjust selectors based on actual HTML)
$('.product-tile').each((i, element) => {
  const $el = $(element);

  const product = {
    product_name: $el.find('.product-title').text().trim(),
    lender_name: $el.find('.bank-name').text().trim(),
    interest_rate_min: parseFloat($el.find('.interest-rate').text().match(/([0-9.]+)/)?.[1] || '0'),
    interest_rate_max: parseFloat($el.find('.interest-rate').text().match(/([0-9.]+)%/g)?.[1]?.replace('%', '') || '0'),
    loan_amount_min: 50000, // Default
    loan_amount_max: parseFloat($el.find('.max-amount').text().replace(/[^0-9]/g, '')),
    min_monthly_income: parseFloat($el.find('.salary-req').text().replace(/[^0-9]/g, '')),
    min_credit_score: parseInt($el.find('.cibil-req').text().replace(/[^0-9]/g, '')) || 650,
    employment_types: ['Salaried', 'Self-Employed'],
    min_age: 21,
    max_age: 60,
    source_url: 'https://www.paisabazaar.com/personal-loan/'
  };

  if (product.product_name && product.lender_name) {
    products.push(product);
  }
});

return products.map(product => ({ json: product }));

// Log execution results
const results = $input.all();
const totalProducts = results.length;

console.log(`Loan Product Discovery completed. Found ${totalProducts} products.`);

return [{ 
  json: { 
    workflow: 'Loan Product Discovery',
    execution_time: new Date().toISOString(),
    products_found: totalProducts,
    status: 'completed'
  } 
}];
